// MainB.java
class Rekening {
    private int saldo;

    Rekening(int saldoAwal) {
        this.saldo = saldoAwal;
    }

    int getSaldo() {
        return saldo;
    }

    void setor(int jumlah) {
        if (jumlah > 0) {
            saldo += jumlah;
        }
    }

    boolean tarik(int jumlah) {
        if (jumlah > 0 && jumlah <= saldo) {
            saldo -= jumlah;
            return true;
        }
        return false;
    }
}

public class MainB {
    public static void main(String[] args) {
        Rekening a = new Rekening(1000);
        a.setor(500);
        System.out.println("Saldo: " + a.getSaldo());
    }
}

